1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  getExportUrl,
7	  getRequirements,
8	  getScenarios,
9	  type Requirement,
10	  type Scenario,
11	} from "@/src/lib/api";
12	import { categoryLabel } from "@/src/components/badges";
13	import { ScoreBar } from "@/src/components/ScoreBar";
14	import { ThemeToggle } from "@/src/components/ThemeToggle";
15	
16	const DEFAULT_SCENARIO_ID = "G60-US";
17	
18	export default function RequirementsPage() {
19	  const router = useRouter();
20	
21	  const [scenarios, setScenarios] = useState<Scenario[] | null>(null);
22	  const [scenarioId, setScenarioId] = useState<string>(DEFAULT_SCENARIO_ID);
23	  const [requirements, setRequirements] = useState<Requirement[] | null>(null);
24	  const [error, setError] = useState<string | null>(null);
25	  const [isFetching, setIsFetching] = useState(true);
26	
27	  const [promptText, setPromptText] = useState("");
28	  const [promptNote, setPromptNote] = useState<string | null>(null);
29	
30	  // Szenarien einmal laden; Standard bleibt G60-US, falls vorhanden, sonst erstes Szenario.
31	  useEffect(() => {
32	    getScenarios()
33	      .then((loaded) => {
34	        setScenarios(loaded);
35	        if (!loaded.some((s) => s.id === DEFAULT_SCENARIO_ID) && loaded[0]) {
36	          setScenarioId(loaded[0].id);
37	        }
38	      })
39	      .catch((err: Error) => setError(err.message));
40	  }, []);
41	
42	  // Anforderungen neu laden bei Szenario-Wechsel.
43	  useEffect(() => {
44	    if (!scenarioId) return;
45	    let cancelled = false;
46	    (async () => {
47	      setIsFetching(true);
48	      try {
49	        const loadedRequirements = await getRequirements(scenarioId);
50	        if (cancelled) return;
51	        setRequirements(loadedRequirements);
52	        setError(null);
53	      } catch (err) {
54	        if (cancelled) return;
55	        setError((err as Error).message);
56	      } finally {
57	        if (!cancelled) setIsFetching(false);
58	      }
59	    })();
60	    return () => {
61	      cancelled = true;
62	    };
63	  }, [scenarioId]);
64	
65	  const isLoading = scenarios === null || isFetching || requirements === null;
66	
67	  /** Platzhalter: Das Prompt-Feld ist noch nicht ans Backend angebunden (eigenes Ticket). */
68	  function handlePromptSubmit() {
69	    const text = promptText.trim();
70	    if (!text) return;
71	    console.log("[prompt submit - placeholder, not wired to backend yet]", text);
72	    setPromptNote(`Received: "${text}" — not connected to the backend yet.`);
73	    setPromptText("");
74	  }
75	
76	  return (
77	    <div className="flex min-h-screen flex-col">
78	      {/* Top bar: volle Breite, nach BMW-Vorbild schlicht weiß/schwarz mit dünner Haarlinie statt Schatten.
79	          Sticky, damit sie beim Scrollen der Seite oben bleibt. */}
80	      <header className="sticky top-0 z-10 w-full border-b border-zinc-200 bg-surface dark:border-zinc-800">
81	        <div className="flex flex-wrap items-center justify-between gap-4 px-6 py-4">
82	          <div>
83	            <h1 className="text-xl font-semibold tracking-tight text-foreground">Signal2Spec</h1>
84	            <p className="text-xs uppercase tracking-wide text-zinc-500 dark:text-zinc-400">
85	              Prioritized requirements for product decisions
86	            </p>
87	          </div>
88	          <div className="flex items-center gap-3">
89	            <label className="flex items-center gap-2 text-sm text-zinc-700 dark:text-zinc-300">
90	              Scenario
91	              <select
92	                value={scenarioId}
93	                onChange={(e) => setScenarioId(e.target.value)}
94	                disabled={!scenarios}
95	                className="rounded-sm border border-zinc-300 bg-surface px-3 py-1.5 text-sm text-foreground focus:border-accent focus:outline-none dark:border-zinc-700"
96	              >
97	                {(scenarios ?? []).map((s) => (
98	                  <option key={s.id} value={s.id}>
99	                    {s.model_name} ({s.market})
100	                  </option>
101	                ))}
102	              </select>
103	            </label>
104	            <a
105	              href={getExportUrl(scenarioId)}
106	              target="_blank"
107	              rel="noopener noreferrer"
108	              className="rounded-sm bg-accent px-4 py-1.5 text-sm font-medium uppercase tracking-wide text-white hover:bg-accent-hover"
109	            >
110	              Export CSV
111	            </a>
112	            <ThemeToggle />
113	          </div>
114	        </div>
115	      </header>
116	
117	      {/* Mitte: Ergebnis-Fenster, 2cm Abstand zu Rand, Top-Bar und Prompt-Leiste */}
118	      <main className="m-[2cm] flex flex-1 flex-col">
119	        <div className="border-t border-b border-zinc-200 bg-surface dark:border-zinc-800">
120	          {error && (
121	            <div className="m-4 rounded-md border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-800 dark:border-rose-800 dark:bg-rose-950 dark:text-rose-300">
122	              {error}
123	            </div>
124	          )}
125	
126	          {!error && isLoading && <p className="p-4 text-sm text-zinc-500 dark:text-zinc-400">Loading…</p>}
127	
128	          {!error && !isLoading && requirements !== null && requirements.length === 0 && (
129	            <p className="p-4 text-sm text-zinc-500 dark:text-zinc-400">No requirements for this scenario yet.</p>
130	          )}
131	
132	          {!error && !isLoading && requirements !== null && requirements.length > 0 && (
133	            <table className="w-full text-left text-sm">
134	              <thead className="border-b border-zinc-200 bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-400">
135	                <tr>
136	                  <th className="px-4 py-3">Score</th>
137	                  <th className="px-4 py-3">Title</th>
138	                  <th className="px-4 py-3">Category</th>
139	                </tr>
140	              </thead>
141	              <tbody>
142	                {requirements.map((req) => (
143	                  <tr
144	                    key={req.id}
145	                    role="link"
146	                    tabIndex={0}
147	                    onClick={() => router.push(`/requirements/${req.id}`)}
148	                    onKeyDown={(e) => {
149	                      if (e.key === "Enter" || e.key === " ") {
150	                        e.preventDefault();
151	                        router.push(`/requirements/${req.id}`);
152	                      }
153	                    }}
154	                    className="cursor-pointer border-b border-zinc-100 last:border-0 hover:bg-accent/5 focus:bg-accent/5 focus:outline-none dark:border-zinc-800 dark:hover:bg-zinc-900 dark:focus:bg-zinc-900"
155	                  >
156	                    <td className="px-4 py-3">
157	                      <ScoreBar score={req.score} />
158	                    </td>
159	                    <td className="px-4 py-3 font-medium text-foreground">{req.title}</td>
160	                    <td className="px-4 py-3 text-zinc-700 dark:text-zinc-300">{categoryLabel(req.category)}</td>
161	                  </tr>
162	                ))}
163	              </tbody>
164	            </table>
165	          )}
166	        </div>
167	      </main>
168	
169	      {/* Unten: Prompt-Eingabe, 1cm Abstand zum Rand unten, 2cm links/rechts */}
170	      <footer className="mx-[3cm] mb-[2cm] flex flex-col gap-2">
171	        {promptNote && <p className="text-xs text-zinc-500 dark:text-zinc-400">{promptNote}</p>}
172	        <div className="flex items-center gap-3">
173	          <input
174	            type="text"
175	            value={promptText}
176	            onChange={(e) => setPromptText(e.target.value)}
177	            onKeyDown={(e) => {
178	              if (e.key === "Enter") handlePromptSubmit();
179	            }}
180	            placeholder="Ask me your questions..."
181	            className="flex-1 rounded-sm border border-zinc-300 bg-surface px-4 py-4 text-sm text-foreground focus:border-accent focus:outline-none dark:border-zinc-700"
182	          />
183	          <button
184	            type="button"
185	            onClick={handlePromptSubmit}
186	            className="rounded-sm bg-accent px-5 py-4 text-sm font-medium uppercase tracking-wide text-white hover:bg-accent-hover"
187	          >
188	            Submit
189	          </button>
190	        </div>
191	      </footer>
192	    </div>
193	  );
194	}
